  { auto _e = save_id(); if (_e) _o->save_id = _e->str(); }
  { auto _e = stores(); if (_e) { _o->stores.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { if(_o->stores[_i]) { _e->Get(_i)->UnPackTo(_o->stores[_i].get(), _resolver); } else { _o->stores[_i] = std::unique_ptr<Tryll::PersistedMutableKbT>(_e->Get(_i)->UnPack(_resolver)); }; } } else { _o->stores.resize(0); } }
