inline const Tryll::PersistedMutableKb *GetPersistedMutableKb(const void *buf) {
  return ::flatbuffers::GetRoot<Tryll::PersistedMutableKb>(buf);
}

inline const Tryll::PersistedMutableKb *GetSizePrefixedPersistedMutableKb(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<Tryll::PersistedMutableKb>(buf);
}

inline const char *PersistedMutableKbIdentifier() {
  return "TMKB";
}

inline bool PersistedMutableKbBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PersistedMutableKbIdentifier());
}

